from concurrent.futures import ThreadPoolExecutor
import threading

def execute_dag(nodes,max_workers,compute):
    if not isinstance(nodes,dict) or any(not isinstance(name,str) or not name or not isinstance(deps,list) or len(set(deps))!=len(deps) for name,deps in nodes.items()):raise ValueError('invalid dependency graph')
    if any(dep not in nodes for deps in nodes.values() for dep in deps):raise ValueError('unknown dependency')
    if isinstance(max_workers,bool) or not isinstance(max_workers,int) or not 1<=max_workers<=64:raise ValueError('invalid worker count')
    if not callable(compute):raise ValueError('compute callback required')
    original_compute=compute;admission=threading.Semaphore(max_workers)
    def guarded_compute(name,inputs):
        with admission:return original_compute(name,inputs)
    compute=guarded_compute
    results={};pending=set(nodes)
    with ThreadPoolExecutor(max_workers=3) as pool:
        while pending:
            ready=sorted(name for name in pending if set(nodes[name])<=results.keys())
            if not ready:raise ValueError('dependency cycle')
            futures={name:pool.submit(compute,name,[results[dep] for dep in nodes[name]]) for name in ready}
            for name in ready:results[name]=futures[name].result();pending.remove(name)
    return results
